from datetime import datetime, timedelta

def next_run(expression: str, after: datetime) -> datetime | None:
    # Split expression into 5 fields: minute, hour, day, month, weekday
    parts = expression.strip().split()
    if len(parts) != 5:
        raise ValueError("Invalid expression: must have 5 fields")

    month_names = {"JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6, 
                   "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12}
    weekday_names = {"SUN": 0, "MON": 1, "TUE": 2, "WED": 3, "THU": 4, "FRI": 5, "SAT": 6}

    def parse_val(v, names):
        if names and v.upper() in names:
            return names[v.upper()]
        if v.isdigit():
            return int(v)
        raise ValueError(f"Invalid value: {v}")

    def parse_field(field, min_val, max_val, names=None):
        if not field:
            raise ValueError("Empty field")
        items = field.split(',')
        res = set()
        for item in items:
            if not item:
                raise ValueError("Empty item in comma-separated list")
            if '/' in item:
                range_p, step_p = item.split('/')
                if not step_p.isdigit():
                    raise ValueError("Step must be an integer")
                step = int(step_p)
                if step <= 0:
                    raise ValueError("Step must be positive")
                if range_p == '*':
                    start, end = min_val, max_val
                elif '-' in range_p:
                    s_str, e_str = range_p.split('-')
                    start = parse_val(s_str, names)
                    end = parse_val(e_str, names)
                    if start > end:
                        raise ValueError("Range start cannot be greater than end")
                else:
                    raise ValueError("Step requires a range or '*' (a/n is not allowed)")
                for v in range(start, end + 1, step):
                    if not (min_val <= v <= max_val):
                        raise ValueError("Value out of range")
                    res.add(v)
            elif '-' in item:
                s_str, e_str = item.split('-')
                start = parse_val(s_str, names)
                end = parse_val(e_str, names)
                if start > end:
                    raise ValueError("Range start cannot be greater than end")
                for v in range(start, end + 1):
                    if not (min_val <= v <= max_val):
                        raise ValueError("Value out of range")
                    res.add(v)
            elif item == '*':
                for v in range(min_val, max_val + 1):
                    res.add(v)
            else:
                v = parse_val(item, names)
                if not (min_val <= v <= max_val):
                    raise ValueError("Value out of range")
                res.add(v)
        return res

    # Parse each field into sets of valid integers
    min_set = parse_field(parts[0], 0, 59)
    hour_set = parse_field(parts[1], 0, 23)
    day_set = parse_field(parts[2], 1, 31)
    month_set = parse_field(parts[3], 1, 12, month_names)
    # Weekday range is 0-7, but 0 and 7 both map to Sunday
    weekday_set_raw = parse_field(parts[4], 0, 7, weekday_names)
    weekday_set = {v % 7 for v in weekday_set_raw}

    day_is_any = (parts[2] == '*')
    weekday_is_any = (parts[4] == '*')

    # Pre-sort for efficient iteration
    sorted_months = sorted(list(month_set))
    sorted_hours = sorted(list(hour_set))
    sorted_mins = sorted(list(min_set))

    # Search for the next valid datetime
    for y in range(after.year, after.year + 11):
        for m in sorted_months:
            if y == after.year and m < after.month:
                continue

            for d in range(1, 32):
                if y == after.year and m == after.month and d < after.day:
                    continue

                try:
                    dt_day = datetime(y, m, d)
                except ValueError:
                    continue # Date doesn't exist (e.g., Feb 30)

                # Check if the day matches the day and weekday criteria
                if day_is_any and weekday_is_any:
                    is_valid_day = True
                elif day_is_any:
                    is_valid_day = (dt_day.weekday() + 1) % 7 in weekday_set
                elif weekday_is_any:
                    is_valid_day = d in day_set
                else:
                    is_valid_day = (d in day_set or (dt_day.weekday() + 1) % 7 in weekday_set)

                if not is_valid_day:
                    continue

                for h in sorted_hours:
                    if y == after.year and m == after.month and d == after.day and h < after.hour:
                        continue
                    for mi in sorted_mins:
                        if y == after.year and m == after.month and d == after.day and h == after.hour and mi < after.minute:
                            continue

                        res = datetime(y, m, d, h, mi)
                        if res > after:
                            return res
    return None
